import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from torchvision import datasets, transforms
from torch.utils.data import DataLoader

import numpy as np
import matplotlib.pyplot as plt
from collections import defaultdict
# Device configuration
# Uses GPU if available, otherwise falls back to CPU
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
# Training hyperparameters
BATCH_SIZE = 128
EPOCHS = 20
LEARNING_RATE = 1e-3
# Lambda controls the sparsity-vs-accuracy tradeoff
# Small lambda  -> better accuracy, less pruning
# Large lambda  -> more pruning, possible accuracy drop
LAMBDA_VALUES = [1e-5, 1e-4, 1e-3]


# If a gate value falls below this threshold,
# we consider that connection effectively pruned
PRUNE_THRESHOLD = 1e-2

# Custom Prunable Linear Layer


class PrunableLinear(nn.Module):
    """
    A custom linear layer where every weight has a learnable gate.

    Final effective weight:
        effective_weight = weight * sigmoid(gate_scores)

    If sigmoid(gate_score) becomes very close to 0,
    the corresponding connection is effectively removed.
    """

    def __init__(self, in_features, out_features):
        super().__init__()

        self.in_features = in_features
        self.out_features = out_features

        # Main learnable weights
        self.weight = nn.Parameter(
            torch.randn(out_features, in_features) * 0.02
        )

        # Standard bias term
        self.bias = nn.Parameter(torch.zeros(out_features))

        # Learnable gate parameters
        # Same shape as weights as required in assignment
        self.gate_scores = nn.Parameter(
            torch.randn(out_features, in_features)
        )

    def forward(self, x):
        # Convert gate scores into values between 0 and 1
        gates = torch.sigmoid(self.gate_scores)

        # Element-wise multiplication
        # Weak connections get suppressed automatically
        pruned_weights = self.weight * gates

        # Standard linear transformation
        return F.linear(x, pruned_weights, self.bias)

    def get_gate_values(self):
        """
        Returns gate values after sigmoid.
        Useful for sparsity calculations.
        """
        return torch.sigmoid(self.gate_scores)

# Self-Pruning Neural Network


class SelfPruningNetwork(nn.Module):
    """
    A feed-forward neural network using custom prunable layers.
    """

    def __init__(self):
        super().__init__()

        # CIFAR-10 images are 3x32x32
        # Flattened size = 3072

        self.fc1 = PrunableLinear(3 * 32 * 32, 1024)
        self.fc2 = PrunableLinear(1024, 512)
        self.fc3 = PrunableLinear(512, 256)
        self.fc4 = PrunableLinear(256, 10)

        self.dropout = nn.Dropout(0.3)

    def forward(self, x):
        # Flatten image
        x = x.view(x.size(0), -1)

        x = F.relu(self.fc1(x))
        x = self.dropout(x)

        x = F.relu(self.fc2(x))
        x = self.dropout(x)

        x = F.relu(self.fc3(x))
        x = self.dropout(x)

        x = self.fc4(x)

        return x

    def get_sparsity_loss(self):
        """
        L1 penalty on gate values.

        Since sigmoid outputs are positive,
        L1 norm becomes simply the sum of gate values.
        """

        sparsity_loss = 0

        for module in self.modules():
            if isinstance(module, PrunableLinear):
                gates = module.get_gate_values()
                sparsity_loss += torch.sum(gates)

        return sparsity_loss

    def calculate_sparsity(self, threshold=1e-2):
        """
        Calculates percentage of pruned weights.

        A weight is considered pruned if:
            gate_value < threshold
        """

        total_weights = 0
        pruned_weights = 0

        for module in self.modules():
            if isinstance(module, PrunableLinear):
                gates = module.get_gate_values()

                total_weights += gates.numel()
                pruned_weights += (gates < threshold).sum().item()

        sparsity_percentage = (
            100.0 * pruned_weights / total_weights
        )

        return sparsity_percentage

    def get_all_gate_values(self):
        """
        Collects all gate values for visualization.
        """

        all_gates = []

        for module in self.modules():
            if isinstance(module, PrunableLinear):
                gates = module.get_gate_values()
                all_gates.extend(gates.detach().cpu().numpy().flatten())

        return np.array(all_gates)

# Data Loading



def get_data_loaders():
    """
    Loads CIFAR-10 dataset.
    """

    transform = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize(
            mean=[0.4914, 0.4822, 0.4465],
            std=[0.2023, 0.1994, 0.2010]
        )
    ])

    train_dataset = datasets.CIFAR10(
        root="./data",
        train=True,
        download=True,
        transform=transform
    )

    test_dataset = datasets.CIFAR10(
        root="./data",
        train=False,
        download=True,
        transform=transform
    )

    train_loader = DataLoader(
        train_dataset,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=2
    )

    test_loader = DataLoader(
        test_dataset,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=2
    )

    return train_loader, test_loader

# Training Function



def train_model(model, train_loader, lambda_value):
    """
    Trains model using:

    Total Loss = Classification Loss + lambda * Sparsity Loss
    """

    optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE)
    criterion = nn.CrossEntropyLoss()

    model.train()

    for epoch in range(EPOCHS):
        total_loss = 0
        total_classification_loss = 0
        total_sparsity_loss = 0

        for images, labels in train_loader:
            images = images.to(DEVICE)
            labels = labels.to(DEVICE)

            optimizer.zero_grad()

            # Forward pass
            outputs = model(images)

            # Standard classification loss
            classification_loss = criterion(outputs, labels)

            # Custom sparsity regularization
            sparsity_loss = model.get_sparsity_loss()

            # Final combined loss
            total_loss_value = (
                classification_loss +
                lambda_value * sparsity_loss
            )

            # Backpropagation
            total_loss_value.backward()

            # Update all parameters
            # including gate scores
            optimizer.step()

            total_loss += total_loss_value.item()
            total_classification_loss += classification_loss.item()
            total_sparsity_loss += sparsity_loss.item()

        current_sparsity = model.calculate_sparsity(
            threshold=PRUNE_THRESHOLD
        )

        print(
            f"Epoch [{epoch+1}/{EPOCHS}] | "
            f"Total Loss: {total_loss:.2f} | "
            f"Classification Loss: {total_classification_loss:.2f} | "
            f"Sparsity Loss: {total_sparsity_loss:.2f} | "
            f"Sparsity: {current_sparsity:.2f}%"
        )

# Evaluation Function



def evaluate_model(model, test_loader):
    """
    Computes test accuracy.
    """

    model.eval()

    correct = 0
    total = 0

    with torch.no_grad():
        for images, labels in test_loader:
            images = images.to(DEVICE)
            labels = labels.to(DEVICE)

            outputs = model(images)

            predictions = torch.argmax(outputs, dim=1)

            total += labels.size(0)
            correct += (predictions == labels).sum().item()

    accuracy = 100.0 * correct / total

    return accuracy

# Plot Gate Distribution



def plot_gate_distribution(gate_values, lambda_value):
    """
    Creates histogram of final gate values.

    A successful pruning strategy should show:
    - many values near 0
    - some important connections away from 0
    """

    plt.figure(figsize=(10, 6))

    plt.hist(gate_values, bins=50)

    plt.title(
        f"Distribution of Gate Values (lambda={lambda_value})"
    )

    plt.xlabel("Gate Values")
    plt.ylabel("Frequency")

    plt.grid(True)

    plt.savefig(f"gate_distribution_lambda_{lambda_value}.png")

    plt.show()

# Main Experiment Loop


def run_experiments():
    """
    Trains models with different lambda values
    and compares sparsity vs accuracy tradeoff.
    """

    train_loader, test_loader = get_data_loaders()

    results = []

    best_model = None
    best_lambda = None
    best_accuracy = 0

    for lambda_value in LAMBDA_VALUES:
        print("\n" + "=" * 70)
        print(f"Training with lambda = {lambda_value}")
        print("=" * 70)

        model = SelfPruningNetwork().to(DEVICE)

        train_model(model, train_loader, lambda_value)

        accuracy = evaluate_model(model, test_loader)

        sparsity = model.calculate_sparsity(
            threshold=PRUNE_THRESHOLD
        )

        print(f"\nFinal Test Accuracy: {accuracy:.2f}%")
        print(f"Final Sparsity Level: {sparsity:.2f}%")

        results.append({
            "lambda": lambda_value,
            "accuracy": accuracy,
            "sparsity": sparsity
        })

        # Keep track of best model
        # We choose based on best accuracy
        if accuracy > best_accuracy:
            best_accuracy = accuracy
            best_model = model
            best_lambda = lambda_value


    # Print Final Results Table


    print("\n" + "=" * 70)
    print("FINAL RESULTS")
    print("=" * 70)

    print(f"{'Lambda':<15} {'Accuracy':<15} {'Sparsity':<15}")

    for result in results:
        print(
            f"{result['lambda']:<15} "
            f"{result['accuracy']:<15.2f} "
            f"{result['sparsity']:<15.2f}"
        )


    # Plot best model gate distribution


    print("\nGenerating gate distribution plot...")

    gate_values = best_model.get_all_gate_values()

    plot_gate_distribution(gate_values, best_lambda)

    print("\nDone.")


# Entry Point


if __name__ == "__main__":
    print(f"Using device: {DEVICE}")

    run_experiments()

